from jinja2 import Template

def create_party_menu(people):
    template = Template("""
        <h1>Party Menu</h1>
        <ul>
        {% for person in people %}
            <li>{{ person['name'] }} - {{ person['food'] }}</li>
        {% endfor %}
        </ul>
    """, autoescape=True)

    return template.render(people=people)

import jinja2

template_str = """
&lt;h1&gt;Dinner Party Invitations&lt;/h1&gt;
&lt;p&gt;Dear {{ name }},&lt;br&gt;We would like to invite you to our special dinner party.&lt;br&gt;Please RSVP by {{ rsvp_date }}.&lt;/p&gt;
"""

def render(name, rsvp_date):
    template = jinja2.Template(template_str, autoescape=True)
    return template.render(name=name, rsvp_date=rsvp_date)

invitations = {
    "Lincoln": {"rsvp_date": "Friday, May 10th"},
    "Churchill": {"rsvp_date": "Saturday, May 11th"}
}

for name, details in invitations.items():
    print(render(name, details["rsvp_date"]))

from random import choice

class DinnerParty:
    def __init__(self):
        self.guests = []

    def invite(self, guest):
        self.guests.append(guest)

    def serve_food(self):
        food = ["pizza", "pasta", "steak"]
        for guest in self.guests:
            print(f"Here is {choice(food)} for {guest}!")

party = DinnerParty()
party.invite("Marie Curie")
party.invite("Albert Einstein")
party.invite("Charles Darwin")

party.serve_food()

